#pragma once
#include "vtf_texture_layout.h"
#include <array>
struct VtfRgbaImageCandidate {uint32_t width=0,height=0;std::vector<uint8_t>rgba;};
inline VtfRgbaImageCandidate decodeVtfMipCandidate(const std::vector<uint8_t>&bytes,uint32_t level,uint32_t frame=0){
 auto layout=readVtfTextureLayoutCandidate(bytes);if(level>=layout.mips.size())throw std::runtime_error("VTF mip selection");if(frame>=layout.frameCount)throw std::runtime_error("VTF frame selection");auto mip=layout.mips[level];mip.offset+=size_t(frame)*mip.size;if(layout.format==0||layout.format==12){VtfRgbaImageCandidate image;image.width=mip.width;image.height=mip.height;image.rgba.assign(bytes.begin()+mip.offset,bytes.begin()+mip.offset+mip.size);if(layout.format==12)for(size_t n=0;n<image.rgba.size();n+=4){auto red=image.rgba[n+2];image.rgba[n+2]=image.rgba[n];image.rgba[n]=red;}return image;}if(layout.format==3){VtfRgbaImageCandidate image;image.width=mip.width;image.height=mip.height;image.rgba.resize(size_t(image.width)*image.height*4);for(size_t pixel=0;pixel<size_t(image.width)*image.height;++pixel){image.rgba[pixel*4]=bytes[mip.offset+pixel*3];image.rgba[pixel*4+1]=bytes[mip.offset+pixel*3+1];image.rgba[pixel*4+2]=bytes[mip.offset+pixel*3+2];image.rgba[pixel*4+3]=255;}return image;}if(layout.format!=13&&layout.format!=20&&layout.format!=15)throw std::runtime_error("DXT1/DXT5 decoder required");
 VtfRgbaImageCandidate result;result.width=mip.width;result.height=mip.height;result.rgba.resize(size_t(mip.width)*mip.height*4);size_t blockSize=layout.format==15?16:8;
 for(uint32_t by=0;by<(mip.height+3)/4;++by)for(uint32_t bx=0;bx<(mip.width+3)/4;++bx){auto block=bytes.data()+mip.offset+(size_t(by)*((mip.width+3)/4)+bx)*blockSize;auto color=block+(layout.format==15?8:0);uint16_t a,b;uint32_t selectors;std::memcpy(&a,color,2);std::memcpy(&b,color+2,2);std::memcpy(&selectors,color+4,4);std::array<std::array<uint8_t,4>,4>palette{};
  auto expand=[](uint16_t v){uint32_t r=(v>>11)&31,g=(v>>5)&63,bl=v&31;return std::array<uint8_t,4>{uint8_t((r<<3)|(r>>2)),uint8_t((g<<2)|(g>>4)),uint8_t((bl<<3)|(bl>>2)),255};};palette[0]=expand(a);palette[1]=expand(b);
  bool four=a>b||layout.format==15;for(size_t k=0;k<3;++k){palette[2][k]=uint8_t(four?(2*palette[0][k]+palette[1][k])/3:(palette[0][k]+palette[1][k])/2);palette[3][k]=uint8_t(four?(palette[0][k]+2*palette[1][k])/3:0);}palette[2][3]=255;palette[3][3]=four?255:0;
  std::array<uint8_t,8>alpha{};uint64_t alphaSelectors=0;if(layout.format==15){alpha[0]=block[0];alpha[1]=block[1];if(alpha[0]>alpha[1]){for(uint32_t n=2;n<8;++n)alpha[n]=uint8_t(((8-n)*alpha[0]+(n-1)*alpha[1])/7);}else{for(uint32_t n=2;n<6;++n)alpha[n]=uint8_t(((6-n)*alpha[0]+(n-1)*alpha[1])/5);alpha[6]=0;alpha[7]=255;}for(size_t n=0;n<6;++n)alphaSelectors|=uint64_t(block[2+n])<<(8*n);}
  for(uint32_t y=0;y<4;++y)for(uint32_t x=0;x<4;++x){uint32_t pixel=y*4+x,xx=bx*4+x,yy=by*4+y;if(xx>=mip.width||yy>=mip.height)continue;auto rgba=palette[(selectors>>(2*pixel))&3];if(layout.format==15)rgba[3]=alpha[(alphaSelectors>>(3*pixel))&7];std::memcpy(result.rgba.data()+(size_t(yy)*mip.width+xx)*4,rgba.data(),4);}
 }return result;
}
